def _лінійно(x, вузли):
    """Кусково-лінійне відображення кута `x` за вузлами [(від, до)] по колу 0–360°:
    `від` зростає, останній відрізок замикається на перший через 360°."""
    x = x % 360.0
    for (x0, y0), (x1, y1) in zip(вузли, вузли[1:] + ((вузли[0][0] + 360.0, вузли[0][1] + 360.0),)):
        xx = x if x >= x0 else x + 360.0
        if x0 <= xx <= x1:
            return (y0 + (xx - x0) * (y1 - y0) / (x1 - x0)) % 360.0
    raise ValueError("кут %r поза вузлами кола" % (x,))

def у_коло_художника(h):
    """Кут тону CIELAB `h` → кут на колі художника (R 0°, G 180°)."""
    return _лінійно(h, _КОЛО)

def з_кола_художника(a):
    """Кут на колі художника → кут тону CIELAB (обернене до `у_коло_художника`)."""
    вузли = sorted((y, x) for x, y in _КОЛО)
    return round(_лінійно(a, tuple(вузли)), 1)

def зсув_на_колі(h, кут):
    """Тон CIELAB, що стоїть на `кут` градусів від `h` на колі художника (знак — напрям)."""
    return з_кола_художника(у_коло_художника(h) + float(кут))

def доповнення(h):
    """Друга сторона комплементу для тону CIELAB `h`: +180° на колі художника, назад у
    CIELAB. Єдине місце, де код будує протилежну сторону (схеми, спектри рис, палітра)."""
    return зсув_на_колі(h, 180.0)

def тепло(h):
    """Теплота тону CIELAB `h`, −1…1 — вісь «жовтіше ↔ синіше» на колі художника (`_тепло_на_колі`, полюси
    `РЕЄСТР["полюси_температури"]`): +1 на жовтому полюсі, −1 на синьому, 0 — рівновіддалені від обох тони (червоний
    θ 0° і зелений θ 180° кола). Одне визначення тепла для всіх читачів; доти тут стояла друга вісь — b*/C* = sin h
    CIELAB, що ставила пурпурово-рожеве (h 0–25) й бірюзове (h 157–180) на теплий бік (крок 23 кореня Річ-колір-межі).
    None — тону нема (теплота не виміряна, не нуль)."""
    return None if h is None else _тепло_на_колі(у_коло_художника(h))

def центри_відношення(h, rel):
    """Центри дуг відношення `rel` (з `RELATIONS`) від тону `h`: кожен зсув — на колі
    художника (`зсув_на_колі`), комплемент — `доповнення`; нульовий зсув — сам `h`."""
    off = RELATIONS[rel][0]
    if off == 180:
        return [доповнення(h)]
    if not off:
        return [h % 360]
    return [зсув_на_колі(h, off), зсув_на_колі(h, -off)]

def дуга_кола(h, пів):
    """Дуга тону CIELAB (від, до) — образ дуги кола художника з центром у тоні CIELAB `h` і пів-шириною
    `пів`° кола (КОЛІР-СХЕМИ, п.18). Ширина дуги — на колі, як і її зсув (`зсув_на_колі`): ±15°
    кола — той самий сектор у будь-якому тоні, а ±15° CIELAB — це ±7° кола в синіх і до ±38° у бурих. Силу
    членства в такій дузі судить `колір_відношення.сила_в_дузі`. Споживач — сім'я очей
    (`palettes.дуга_очей`) і ролі схем (`palettes.дуга`, 2.14-Б); спектри рис лишились кутами CIELAB."""
    return (з_кола_художника(у_коло_художника(h) - float(пів)) % 360.0,
            з_кола_художника(у_коло_художника(h) + float(пів)) % 360.0)

def arc(c,half):
    """Дуга (c − half, c + half) по модулю 360."""
    return ((c-half)%360, (c+half)%360)

def in_arc(h,a):
    """Чи кут h лежить у дузі a, з переходом через 0°."""
    lo,hi=a; return (lo<=h<=hi) if lo<=hi else (h>=lo or h<=hi)


# ═══ ЛІЧБА КОЛА: КУТ І ДУГА ═══
# Кут — градуси на будь-якому колі тону: тон CIELAB чи координата кола художника. На якому колі лічити, обирає
# читач (середина дуги CIELAB і середина її образу на колі художника — різні тони). Дуга (від, до) іде за ходом —
# проти годинникової стрілки, від `від` до `до` — і замкнена з обох країв, як `in_arc`. (x, x) — одна точка x
# (ширина 0), усе коло — `ПОВНЕ_КОЛО` (ширина 360; `in_arc` приймає його на всьому [0, 360]). Читачі тримали
# (x, x) то точкою, то всім колом (`… or 360`, «(x, x) — усе коло»), дошка 11298. Кути й кінці дуг, які
# повертають функції нижче, лежать у [0, 360); виняток — `ПОВНЕ_КОЛО`.
ПОВНЕ_КОЛО = (0.0, 360.0)

def нормувати(кут):
    """Кут у [0, 360). Від'ємне −ε після `% 360` дає 360.0, тож межу закрито явно."""
    к = float(кут) % 360.0
    return 0.0 if к >= 360.0 else к

def різниця_на_колі(a, b):
    """a − b коротшим шляхом по колу, [−180, 180): знак — напрям від b до a (+ — за ходом); протилежні — −180."""
    return нормувати(float(a) - float(b) + 180.0) - 180.0

def відстань_тонів(a, b):
    """Кут між a і b коротшим шляхом, [0, 180]; симетрична: |a − b| однаковий в обидва боки."""
    d = abs(float(a) - float(b)) % 360.0
    return min(d, 360.0 - d)

def кругове_середнє(тони, ваги=None):
    """Зважене кругове середнє кутів `тони`: (середній кут у [0, 360) чи None, R). R — довжина середнього одиничного
    вектора, 0…1: 1 — кути збіглися, 0 — розкидані врівноваж (тоді середнього нема, None). Кожен кут — одиничний
    вектор незалежно від хроми: це середнє самих тонів (розсіяння рис, дуги), а не середнє кольорів — для кольорів
    середнє точок у Lab чи OKLab, яке зважує тон хромою. Коло — те, на якому дано кути (CIELAB чи художника).
    Ваги без суми (0) — R = 0; R ≤ 1 і тоді, коли округлення дає 1 + ε. Порожньо — None."""
    тони = [float(h) for h in тони]
    if not тони:
        return None
    ваги = [float(w) for w in ваги] if ваги else [1.0] * len(тони)
    S = sum(ваги) or 1.0
    x = sum(w * math.cos(math.radians(h)) for h, w in zip(тони, ваги)) / S
    y = sum(w * math.sin(math.radians(h)) for h, w in zip(тони, ваги)) / S
    R = min(1.0, (x * x + y * y) ** 0.5)         # однакові кути дають 1 + ε: √(−2·ln R) тоді комплексне
    return (нормувати(math.degrees(math.atan2(y, x))) if R > 1e-12 else None), R

def кругова_скв(тони, ваги=None):
    """Кругова СКВ кутів, градуси: √(−2·ln R) з R `кругове_середнє` (R знизу — 1e−9, тож розкидані врівноваж
    дають ≈ 371°, а не ∞). Неперервна міра розкиду по всіх кутах і вагах, не max − min. Порожньо — None."""
    с = кругове_середнє(тони, ваги)
    return None if с is None else math.degrees((-2.0 * math.log(max(с[1], 1e-9))) ** 0.5)

def зсув_за_ходом(від, кут):
    """Скільки градусів від `від` до `кут` за ходом, [0, 360): зсув кута від початку дуги."""
    return нормувати(float(кут) - float(від))

def ширина_дуги(дуга):
    """Довжина дуги (від, до) за ходом, 0…360: (x, x) — 0; `ПОВНЕ_КОЛО`, як і будь-яка дуга з до − від ≥ 360, — 360."""
    від, до = float(дуга[0]), float(дуга[1])
    return 360.0 if до - від >= 360.0 else зсув_за_ходом(від, до)

def _дуга(від, ширина):
    """Дуга з початку й ширини: ширина ≥ 360 — `ПОВНЕ_КОЛО`, ≤ 0 — точка `від`."""
    if ширина >= 360.0:
        return ПОВНЕ_КОЛО
    від = нормувати(від)
    return (від, нормувати(від + max(float(ширина), 0.0)))

def в_дузі_пів(h, дуга):
    """Чи h на напіввідкритій дузі [від, до): без верхнього краю, щоб сусідні дуги ділили межу, а не перетиналися.
    (x, x) — порожня, `ПОВНЕ_КОЛО` — усе [0, 360). Кути — у [0, 360), як для `in_arc`."""
    lo, hi = дуга
    return (lo <= h < hi) if lo <= hi else (h >= lo or h < hi)

def точка_дуги(дуга, частка):
    """Кут на дузі на `частка` її ширини від `від` за ходом: 0 — початок, 0.5 — середина, 1 — кінець."""
    return нормувати(float(дуга[0]) + float(частка) * ширина_дуги(дуга))

def середина_дуги(дуга):
    """Середина дуги за ходом — на тому колі, на якому дано дугу (`точка_дуги` з часткою 0.5)."""
    return точка_дуги(дуга, 0.5)

def тони_дуги(дуга, крок=1.0):
    """Кути дуги від `від` кроком `крок` за ходом, кінець — коли крок у нього влучає; на `ПОВНЕ_КОЛО` початок не
    повторюється."""
    крок = float(крок)
    if крок <= 0.0:
        raise ValueError("крок дуги має бути додатним")
    ш = ширина_дуги(дуга)
    n = math.ceil(ш / крок) if ш >= 360.0 else math.floor(ш / крок) + 1
    return [нормувати(float(дуга[0]) + k * крок) for k in range(n)]

def градуси_дуги(дуга):
    """Множина цілих градусів g, чий відрізок [g, g + 1) зачіпає дугу: від ⌊від⌋ до градуса кінця за ходом.
    (x, x) — один градус, `ПОВНЕ_КОЛО` і дуга, обидва кінці якої в одному градусі через усе коло, — усі 360."""
    від = float(дуга[0])
    перший = math.floor(від)
    кроків = min(math.floor(від - перший + ширина_дуги(дуга)), 359)
    return {(перший + k) % 360 for k in range(кроків + 1)}

def дуга_в_дузі(внутрішня, зовнішня):
    """Чи дуга `внутрішня` вся лежить у дузі `зовнішня`: обидва її кінці в зовнішній і кінець не раніше за початок
    (зсуви від початку зовнішньої). Кінці порівнюються самі, без суми зсуву й ширини, тож спільний кінець — усередині."""
    ш = ширина_дуги(зовнішня)
    if ш >= 360.0:
        return True
    if ширина_дуги(внутрішня) >= 360.0:
        return False
    з0, з1 = зсув_за_ходом(зовнішня[0], внутрішня[0]), зсув_за_ходом(зовнішня[0], внутрішня[1])
    return з0 <= з1 <= ш

def розширити_дугу(дуга, допуск):
    """Дуга, ширша на `допуск`° з кожного боку (від'ємний — вужча до середини); ширина ≥ 360 — `ПОВНЕ_КОЛО`."""
    ш = ширина_дуги(дуга)
    if ш >= 360.0:
        return ПОВНЕ_КОЛО
    нова = ш + 2.0 * float(допуск)
    if нова <= 0.0:
        с = середина_дуги(дуга)
        return (с, с)
    return _дуга(float(дуга[0]) - float(допуск), нова)

def перетин_дуг(a, b):
    """Спільні шматки двох замкнених дуг — список дуг, найширша першою (рівні — від меншого кута початку);
    [] — спільної точки нема. Шматків буває два (кожна дуга покриває обидва кінці іншої); дотик краями — точка.
    Кінці шматків — ті самі числа, що й кінці дуг (після `нормувати`)."""
    wa, wb = ширина_дуги(a), ширина_дуги(b)
    if wa >= 360.0:
        return [ПОВНЕ_КОЛО if wb >= 360.0 else _дуга(b[0], wb)]
    if wb >= 360.0:
        return [_дуга(a[0], wa)]
    s = зсув_за_ходом(a[0], b[0])
    шматки = []
    for п, к in ((s, s + wb), (s - 360.0, s + wb - 360.0)):   # b і її образ на оберт раніше: дотик через a[0]
        lo, hi = max(п, 0.0), min(к, wa)
        if lo <= hi:
            від = нормувати(b[0] if п > 0.0 else a[0])
            шматок = (lo, hi, від, від if lo == hi else нормувати(b[1] if к < wa else a[1]))
            if шматок not in шматки:
                шматки.append(шматок)
    шматки.sort(key=lambda ш: (-(ш[1] - ш[0]), ш[2]))
    return [(ш[2], ш[3]) for ш in шматки]

def об_єднати_дуги(a, b):
    """Найвужча дуга, що тримає обидві: коло без найширшої щілини між ними; щілини нема — `ПОВНЕ_КОЛО`. Із двох
    однаково широких щілин виключається та, що починається з меншого кута: відповідь не залежить від порядку дуг.
    Кінці — ті самі числа, що й кінці дуг (після `нормувати`)."""
    wa, wb = ширина_дуги(a), ширина_дуги(b)
    if wa >= 360.0 or wb >= 360.0:
        return ПОВНЕ_КОЛО
    s = зсув_за_ходом(a[0], b[0])
    a0, a1, b0, b1 = (нормувати(x) for x in (a[0], a[1], b[0], b[1]))
    відрізки = [(0.0, wa, a0, a1)]   # зсув від a[0]: (початок, кінець, кут початку, кут кінця)
    відрізки += [(s, s + wb, b0, b1)] if s + wb <= 360.0 else [(s, 360.0, b0, a0), (0.0, s + wb - 360.0, a0, b1)]
    відрізки.sort()
    злиті = [list(відрізки[0])]
    for п, к, кп, кк in відрізки[1:]:
        if п <= злиті[-1][1]:
            if к > злиті[-1][1]:
                злиті[-1][1], злиті[-1][3] = к, кк
        else:
            злиті.append([п, к, кп, кк])
    щілини = [(злиті[i][1], злиті[i + 1][0], злиті[i][3], злиті[i + 1][2]) for i in range(len(злиті) - 1)]
    щілини.append((злиті[-1][1], злиті[0][0] + 360.0, злиті[-1][3], злиті[0][2]))
    п, к, кп, кк = min(щілини, key=lambda щ: (-(щ[1] - щ[0]), щ[2]))
    if к - п <= 0.0:
        return ПОВНЕ_КОЛО
    return (кк, кп)

# ═══ ВІДНОШЕННЯ ТОНУ: ВІКНА НА КОЛІ ХУДОЖНИКА ═══
# Визначення відношень кольорів — тут, одне для всіх читачів (крок 24а кореня Річ-колір-межі): вікна відстані тонів
# на колі художника, вікна різниці тону ΔH* ближніх класів із допуском виміру, край і згасання дуги тону, межі
# категорій тону. Силу за ними рахує `колір_відношення` (гаус межі, певність тону, інтервали вікон слів) — їхній
# читач; дослідження й вибір меж — шапка `колір_відношення` і розділ «ДУГА ТОНУ» там само.
СІГМА_МЕЖІ = 5.0        # розмиття межі категорії тону, градуси кола художника
# ДУГА_ВІДЛУННЯ — той самий голос тону: пів сектора 12-кольорового кола (Р2а).
ДУГА_ВІДЛУННЯ = 15.0
СЕКТОР_КОЛА = 30.0      # крок 12-кольорового кола художника (R 0°, RO 30°, O 60°, …)
_ДВ = ДУГА_ВІДЛУННЯ
_СК = СЕКТОР_КОЛА
_тр = RELATIONS["triadic"]
_рз = RELATIONS["split"]
_кп = RELATIONS["complementary"]
# Клітини кола для вузлів тону вікна (`колір_відношення.певність_тону`): чверть сектора 12-кольорового кола, 7.5° —
# вузли дуги вікна слова (кемел 55–95: 55, 60, 67.5, …, 90, 95) густіші за кроки воріт хроми решітки за тоном.
КЛІТИНИ_ТОНУ = tuple((нормувати(і * СЕКТОР_КОЛА / 4), нормувати((і + 1) * СЕКТОР_КОЛА / 4)) for і in range(48))
# Вікна відстані тонів на колі: (від, до, нижня межа відкрита). Межі — `колір_річ.відношення`
# (Р2а, K-PAL-05, `RELATIONS`), нові — аналогова (1–2 сектори) і квадрат (90 ± пів сектора).
ВІКНА_ТОНУ = {
    "same_hue": (0.0, _ДВ, False),                          # той самий сектор: відлуння, повтор
    "adjacent": (_ДВ, _ДВ + _СК, True),                     # сусідній сектор (K-PAL-04)
    "near_hue": (0.0, _ДВ + _СК, False),                    # той самий чи сусідній (K-COL-02)
    "analogous": (_ДВ, _ДВ + 2 * _СК, True),                # аналогова: 1–2 сектори поруч
    "square": (90.0 - _ДВ, 90.0 + _ДВ, False),              # квадрат — пара тетради
    "triadic": (_тр[0] - _тр[1], _тр[0] + _тр[1], False),
    "split": (_рз[0] - _рз[1], _рз[0] + _рз[1], False),
    "complementary": (_кп[0] - _кп[1], 180.0, False),       # K-COL-03 §4, K-PAL-05: від 150°
}
# Вікна різниці тону ΔH* для ближніх класів (K-COL-11): (зовнішня межа, внутрішній клас, віднімається) —
# той самий тон |ΔH*| ≤ 3 (практики: пів кроку атласу Манселла /8, сторінки Nearly Neutrals /4, назви ISCC-NBS
# /2 і /1 — ±2…3.3); ближній ≤ 9 і аналоговий ≤ 15 — ті самі пропорції 1 : 3 : 5, що 15 : 45 : 75° кола.
# Сусідній і аналоговий — зовнішнє вікно мінус «той самий» (кільце навколо нуля). Класу поза словником
# ΔH* не судить (далекі відношення — лише коло); `ВІКНА_ΔH = {}` — кодування Р2а без поправки практиків.
ВІКНА_ΔH = {
    "same_hue": (3.0, None),
    "near_hue": (9.0, None),
    "adjacent": (9.0, "same_hue"),
    "analogous": (15.0, "same_hue"),
}
СІГМА_ΔH = 1.0          # розмиття межі ΔH* — та сама частка пів-ширини, що СІГМА_МЕЖІ / ДУГА_ВІДЛУННЯ (5 / 15)
МЕЖА_БЛИЗЬКИХ = 90.0    # ближні класи за ΔH* — не далі чверті кола (Moon–Spencer ±43°, PCCS проміжний 60–105°)
# ДОПУСК ВИМІРУ (2.14, рядки 2860, 2861). Межі ближніх класів — для справжніх кольорів, а виміряний тон має похибку:
# ΔH* між кадрами однієї речі (`каталог_кадри`, 985 пар, C* ≥ 12) — p90 2.13, на будь-якій світлоті й хромі
# (L* < 35 — 2.33, 35–65 — 1.91, ≥ 65 — 2.09; C* < 30 — 2.20, ≥ 30 — 2.01), тож p90 одного виміру — 2.13 / √2 = 1.5.
# Каст крамниці (медіана a*b* нейтралей, 25 крамниць) розходиться менше: σ a* 0.45, b* 0.68 — тону пари не додає.
# Похибка стала в ΔH*, тож допуск пари — у вікні ΔH*: межа плюс похибка обох (√(Uа² + Uб²)). Вікна ΔH* практиків —
# для приглушених (рядок 2860): насиченим межа ширшає за вагою тону CIE94 S_H = 1 + 0.015·C* (C* — середня
# геометрична пари; та сама вага, що в допусках ΔE94 і CIEDE2000). Коло художника похибки не додає: там, де опори
# `_КОЛО` розтягують CIELAB (помаранчево-бурі 54–69° — учетверо) і ±15° кола вужчі за похибку виміру, судить вікно ΔH*
# (об'єднання класу); допуск на колі зсунув би межу й у червоних, де вимір точний (аркуш 2.14: червоне × помаранчеве
# на Δколо 16 — «так»). Вікно слова похибки не має (невизначеність — у його межах).
ПОХИБКА_ТОНУ = 1.5      # ΔH*, p90 похибки тону одного виміру (`проби/коло_тону_похибка_214.py`)
ВАГА_ТОНУ_ХРОМИ = 0.015 # k S_H = 1 + k·C* (CIE94); 0 — вікна ΔH* без ваги хроми

# Дуга тону — вікно з силою, що згасає до країв (шапка розділу «ДУГА ТОНУ» `колір_відношення`).
КРАЙ_ДУГИ = 0.5         # сила на самому краю дуги: від неї річ «у дузі» (несе тон, зарахована носієм)
КІНЕЦЬ_ЗГАСАННЯ = 0.05  # сила, нижче якої тон поза вікном без сумніву
ХРОМА_ПРИГЛУШЕНИХ = РЕЄСТР["хрома_приглушених"]["val"]   # C* 34: верх смуги приглушених (`palettes.ПРИГЛУШЕНО`)
ЗАПАС_ПРИГЛУШЕНИХ = 10.0   # кінець згасання приглушених, градуси CIELAB: запас суду K-PAL-03 (очима — межа)
ΔH_КРАЮ = 2.0 * ХРОМА_ПРИГЛУШЕНИХ * math.sin(math.radians(ЗАПАС_ПРИГЛУШЕНИХ) / 2.0)   # ΔH* ≈ 5.9 від краю дуги
# Межі категорій тону насичених (C* > 34), h* CIELAB — зі статистики назв крамниць (п.9: вікно — вжиток крамниць), раз:
# для сусідніх за медіаною слів — тон рівної помилки (частка першого слова за межею = частці другого перед нею;
# `проби/коло_ролі_категорії_8530.py`); код слів не читає (п.12). Значення — чи межу підтвердили очима: за
# краєм дуги, поки річ і центр дуги в одній категорії, а межа з боку речі ввімкнена, згасання — запасом приглушених
# (`_сила_за_краєм`); вимкнена межа лишає жорсткий край, а категорії ділить, як і ввімкнена.
МЕЖІ_КАТЕГОРІЙ = {
    23.6: True,     # рожевий (медіана 2.8) | червоний (32.0); очима «так» 10 з 10
    36.9: False,    # червоний | помаранчевий (45.4); очима хибні «так»: червоні h37–40 у помаранчевих ролях — червоні (4 з 10)
    62.5: False,    # помаранчевий | жовтий (92.2); очима хибні «так»: помаранчеве в жовтій ролі, буре й кемел в оливковій (3 з 10)
    101.8: False,   # жовтий | зелений (139.4); очима хибні «так»: жовте в лаймових ролях, олива в охристій (4 з 10)
    192.3: False,   # зелений | блакитний (267.4); очима хибні «так»: смарагд і трава в лаймових ролях; вимір фіолетового пальта h147 (2 з 10)
    276.6: False,   # блакитний | синій (289.6); очима хибні «так»: синя сукня у фіолетовому вікні (1 з 3)
    303.2: False,   # синій | фіолетовий (323.2); очима хибні «так»: фіолетові штани в синій ролі; вимір бурого светра h303 (3 з 10)
    347.7: False,   # фіолетовий | рожевий; очима хибні «так»: фуксія у фіолетових ролях, рожеве в кораловій (6 з 10)
}

# ═══ СІМ'Ї КОЛЬОРУ: ОДНЕ ВИЗНАЧЕННЯ ДЛЯ РЕЧІ, ПАЛІТРИ Й РИСИ ═══
# Сім'я — область у Lab: об'єднання клітинок ISCC–NBS її блоків (таблиця `колір_сім_ї_вікна.md`),
# перенесене з Munsell H/V/C тим самим ланцюжком renotation, що й Lab-апроксимації лабораторії. Решітка
# з кроком 1 ΔE*ab дає мітку вузла; сила сім'ї в точці — частка гаусового ядра (σ — поріг помітності
# разом із похибкою виміру) на вузлах сім'ї, тож на межі сили діляться, а не перемагає порядок рядків. Байт
# вузла — сім'я тону × рівні + частка тону: решта сили вузла — ахроматичній. Частку дають ворота хроми Мансела
# вузла з меж ISCC-NBS його тону й світлоти («-ish gray» — тон-прикметник, далі — іменник тону), тож тон згасає з
# хромою всередині блоку, а не блоком цілим, і межа в C* різна за тоном і світлотою; у приглушеному (C ≤ 4)
# помаранчева, жовта й рожева поза рожевим підтоном — бура (беж, кемел, хакі; K-COL-06, K-COL-12). Метод і
# джерела — `ворота_хроми` і `приглушене` генератора `лабораторія/колір_сім_ї_решітка.py`.
# Вузли без даних (поза оболонкою точок renotation чи гамутом sRGB з полем) несуть «невідомо»; частку ядра за
# кінцями шкали світлоти (L* < 0, L* > 100 і вузли, світліші за біле чи темніші за чорне свого стовпця, — кольорів
# там нема) не лічать ні сім'єю, ні «невідомо».
НЕВІДОМО = "невідомо"
_ДАНІ_СІМЕЙ = {}


def _решітка():
    """Розпаковує мітки решітки (байт на вузол, 255 — даних нема, «поза_шкалою» — за кінцем шкали світлоти)
    і звіряє їхній SHA-256."""
    if "мітки" not in _ДАНІ_СІМЕЙ:
        сирі = zlib.decompress(base64.b85decode("".join(_РЕШІТКА_ДАНІ)))
        if hashlib.sha256(сирі).hexdigest() != _РЕШІТКА_СІМЕЙ["sha256"]:
            raise ValueError("решітка сімей не збігається з породженою")
        _ДАНІ_СІМЕЙ["мітки"] = сирі
    return _ДАНІ_СІМЕЙ["мітки"]


def _решітка_ролей():
    """Розпаковує ролі нейтралі вузлів (байт на вузол тієї самої коробки: 0 — нема, 1… — номер ролі
    `_РОЛІ_НЕЙТРАЛІ["ролі"]` + 1) і звіряє їхній SHA-256."""
    if "ролі" not in _ДАНІ_СІМЕЙ:
        сирі = zlib.decompress(base64.b85decode("".join(_РЕШІТКА_РОЛЕЙ)))
        if hashlib.sha256(сирі).hexdigest() != _РОЛІ_НЕЙТРАЛІ["sha256"]:
            raise ValueError("решітка ролей нейтралі не збігається з породженою")
        _ДАНІ_СІМЕЙ["ролі"] = сирі
    return _ДАНІ_СІМЕЙ["ролі"]


def _ядро(σ):
    """Зсуви вузлів у кулі радіуса охоплення·σ навколо цілої точки (кеш за σ з точністю 0.01)."""
    ключ = round(σ, 2)
    if ключ not in _ДАНІ_СІМЕЙ:
        r = int(math.ceil(РЕЄСТР["охоплення_ядра"]["val"] * ключ)) + 1
        _ДАНІ_СІМЕЙ[ключ] = [(dL, da, db) for dL in range(-r, r + 1) for da in range(-r, r + 1)
                             for db in range(-r, r + 1) if dL * dL + da * da + db * db <= r * r]
    return _ДАНІ_СІМЕЙ[ключ]


def _ваги(lab, похибка, ролі=False):
    """Ваги ядра точки Lab: [сім'ї…, «невідомо»] і з `ролі` — ваги ролей нейтралі в барвних сім'ях
    [—, нейві, кремовий] (частка тону вузла з роллю); None — вхід не точка. Одне ядро для `сили_сімей` і
    `сили_нейтралі`."""
    if lab is None or not all(isinstance(x, (int, float)) and math.isfinite(x) for x in lab):
        return None
    σ = math.hypot(РЕЄСТР["поріг_помітності"]["val"], float(похибка or 0.0))
    межа = РЕЄСТР["охоплення_ядра"]["val"] * σ
    мітки, сім_ї, поза = _решітка(), _РЕШІТКА_СІМЕЙ["сім_ї"], _РЕШІТКА_СІМЕЙ["поза_шкалою"]
    роль = _решітка_ролей() if ролі else None
    ваги_ролей = [0.0] * (len(_РОЛІ_НЕЙТРАЛІ["ролі"]) + 1)
    (L0, L1), (a0, a1), (b0, b1) = _РЕШІТКА_СІМЕЙ["коробка"]
    na, nb = a1 - a0 + 1, b1 - b0 + 1
    L, a, b = (float(x) for x in lab)
    cL, ca, cb = round(L), round(a), round(b)
    ваги = [0.0] * (len(сім_ї) + 1)
    ахр = сім_ї.index("achromatic")
    рівні = _РЕШІТКА_СІМЕЙ["рівні_воріт"]
    for dL, da, db in _ядро(σ):
        вL, вa, вb = cL + dL, ca + da, cb + db
        d2 = (вL - L) ** 2 + (вa - a) ** 2 + (вb - b) ** 2
        if d2 > межа * межа:
            continue
        if not L0 <= вL <= L1:
            continue
        і = ((вL - L0) * na + (вa - a0)) * nb + (вb - b0) if a0 <= вa <= a1 and b0 <= вb <= b1 else None
        мітка = мітки[і] if і is not None else None
        if мітка == поза:
            continue
        w = math.exp(-d2 / (2 * σ * σ))
        if мітка is None or мітка >= len(сім_ї) * рівні:
            ваги[-1] += w
            continue
        сім, частка = divmod(мітка, рівні)
        if сім != ахр:
            частка /= рівні - 1
            ваги[ахр] += w * (1.0 - частка)
            w *= частка
            if роль is not None and роль[і]:
                ваги_ролей[роль[і]] += w
        ваги[сім] += w
    return ваги, ваги_ролей


def сили_сімей(lab, похибка=0.0):
    """Сили сімей точки Lab: {код: частка}, разом з «невідомо» — 1; порожній вхід — {«невідомо»: 1}.

    `похибка` — стандартна похибка виміру кольору в ΔE*ab (розкид значення); σ ядра — її сума
    з порогом помітності, тож сила згасає до межі сім'ї на ширині, якої око й вимір не розрізняють.
    Кінець шкали світлоти — не межа з сусідньою сім'єю: вузли ядра світліші за біле чи темніші за чорне
    (поза L коробки — уся шкала 0–100 — і мітка «поза_шкалою») не лічимо, і сила — частка лише тієї частини
    ядра, що серед можливих кольорів (рішення менеджера 05.11, паспорт `Річ-колір-межі`)."""
    вихід = _ваги(lab, похибка)
    if вихід is None:
        return {НЕВІДОМО: 1.0}
    ваги, сім_ї = вихід[0], _РЕШІТКА_СІМЕЙ["сім_ї"]
    разом = sum(ваги)
    if разом <= 0:
        return {НЕВІДОМО: 1.0}
    сили = {к: ваги[і] / разом for і, к in enumerate(сім_ї) if ваги[і] > 0}
    if ваги[-1] > 0:
        сили[НЕВІДОМО] = ваги[-1] / разом
    return dict(sorted(сили.items(), key=lambda п: -п[1]))


def сім_ї_кольору(lab, похибка=0.0):
    """[(код, сила)] за спаданням сили — найсильніша сім'я й кожна інша значна (сила ≥ `значна_сила`) за тим самим σ.

    Колір на межі сімей належить усім значним із силою кожної: на межі двох — пара, на стику трьох-чотирьох — усі,
    без обрізання до пари, бо при майже рівних силах обрати дві — вгадування, а не вимір (рішення менеджера 06.11,
    13776). «Невідомо» — лише вимір без даних (сила «невідомо» більша за силу кожної сім'ї)."""
    return сім_ї_за_силами(сили_сімей(lab, похибка))


def сім_ї_за_силами(сили):
    """`сім_ї_кольору` за вже порахованими силами `сили_сімей` (той самий вердикт без другого проходу ядра)."""
    сім_ї = [(к, с) for к, с in сили.items() if к != НЕВІДОМО]
    if not сім_ї or сили.get(НЕВІДОМО, 0.0) > сім_ї[0][1]:
        return [(НЕВІДОМО, сили.get(НЕВІДОМО, 1.0))]
    return сім_ї[:1] + [(к, с) for к, с in сім_ї[1:] if с >= РЕЄСТР["значна_сила"]["val"]]


СТИК = "стик"


def на_стику(вердикт):
    """Чи вердикт `сім_ї_кольору` — стик сімей: значних три й більше (рішення менеджера 06.11, 13776)."""
    return len(вердикт) >= 3


def сім_я_кольору(lab, похибка=0.0):
    """(код сім'ї, сила) найсильнішої сім'ї; («невідомо», сила) — лише вимір без даних; на стику трьох і більше
    значних сімей — («стик», сума їхніх сил): найсильнішу там не беремо, одну сім'ю судить модель із фото (рішення
    менеджера 06.11, 13776). Усі значні — `сім_ї_кольору`."""
    вердикт = сім_ї_кольору(lab, похибка)
    if на_стику(вердикт):
        return СТИК, sum(с for _, с in вердикт)
    return вердикт[0]


def _тепло_на_колі(θ):
    """Вісь «жовтіше ↔ синіше» на колі художника: +1 на жовтому полюсі, −1 на синьому, лінійно за дугами."""
    жовтий, синій = РЕЄСТР["полюси_температури"]["val"]
    до_ж, до_с = відстань_тонів(θ, жовтий), відстань_тонів(θ, синій)
    return (до_с - до_ж) / (до_с + до_ж)


def тепло_кольору(lab, похибка=0.0):
    """Теплота кольору `lab` за віссю `тепло`; None — хрома в межах σ = √(JND² + похибка²): тон не визначений,
    бік не стверджується (ні теплий, ні холодний — не нуль)."""
    _, C, h = lch(lab)
    if C <= math.hypot(РЕЄСТР["поріг_помітності"]["val"], float(похибка or 0.0)):
        return None
    return тепло(h)


def дуга_температури(бік):
    """Дуга тону CIELAB (від, до) за ходом, на якій `тепло` має знак боку: «тепла» — > 0 (жовтий полюс усередині),
    «холодна» — < 0 (синій). Кінці — тони, рівновіддалені від обох полюсів на колі художника (`тепло` = 0)."""
    жовтий, синій = РЕЄСТР["полюси_температури"]["val"]
    шов = середина_дуги((жовтий, синій))
    дуга = {"тепла": (нормувати(шов + 180.0), шов), "холодна": (шов, нормувати(шов + 180.0))}[бік]
    return (з_кола_художника(дуга[0]), з_кола_художника(дуга[1]))


def температура_сім_ї(lab, похибка=0.0):
    """(код сім'ї, відносна температура) — >0 тепліша (жовтіша) версія сім'ї, <0 холодніша (синіша).

    Барвна сім'я — зсув уздовж осі від центру тону сім'ї; ахроматична — підтон за тією самою віссю;
    хрома в межах σ (тон не визначений), сім'я «невідомо» чи стик сімей — температура None."""
    код, _ = сім_я_кольору(lab, похибка)
    if код in (НЕВІДОМО, СТИК):
        return код, None
    т = тепло_кольору(lab, похибка)
    if т is None or код == "achromatic":
        return код, т
    return код, т - _тепло_на_колі(_РЕШІТКА_СІМЕЙ["центри_θ"][код])


# ═══ НЕЙТРАЛЬ K-COL-06: РОЛЬ ЗА СІМ'ЯМИ МОДУЛЯ ═══
# Нейтраль — роль, а не відсутність тону (рішення менеджера 06.11, 07.11, 13891). K-COL-06 зве нейтраллю чорний,
# білий, сірі й нейві, кемел, беж, буре, кремовий, оливу й хакі. Назва, що є сім'єю модуля, — уся сім'я (ахроматична,
# бура з бежем, кемелом і хакі, олива: `сім_ї_нейтралі` генератора); назва, що в ISCC-NBS лише частина сім'ї, — її
# блоки (нейві — темні блоки синьої, кремовий — 89 pale yellow: `ролі_нейтралі` генератора). Сила нейтралі в точці —
# частка того самого ядра `сили_сімей` на вузлах ролі, тож межа «нейтраль ↔ колір» — межа сімей і блоків джерела, а не
# коридори тону й хроми (T3 без джерела, зняті кроком 26). Тепла чи холодна — лише апріорі в поясненні (K-COL-06,
# BREAKS): фільтр нею — «ЗНАХІДКА».
ВИД_РОЛІ = {"achromatic": "ахроматична", "brown": "тепла", "olive": "тепла", "нейві": "холодна", "кремовий": "тепла"}
КОЛІР = "колір"


def сили_нейтралі(lab, похибка=0.0):
    """Сили ролі в точці Lab тим самим ядром, що `сили_сімей`: {«ахроматична», «тепла», «холодна» — нейтраль
    K-COL-06 за видом, «колір» — решта барвних сімей, «невідомо» — вузли без даних}, разом — 1."""
    вихід = _ваги(lab, похибка, ролі=True)
    if вихід is None:
        return {НЕВІДОМО: 1.0}
    ваги, ваги_ролей = вихід
    сім_ї = _РЕШІТКА_СІМЕЙ["сім_ї"]
    разом = sum(ваги)
    if разом <= 0:
        return {НЕВІДОМО: 1.0}
    сили = dict.fromkeys(("ахроматична", "тепла", "холодна", КОЛІР, НЕВІДОМО), 0.0)
    for і, к in enumerate(сім_ї):
        сили[ВИД_РОЛІ[к] if к in _РОЛІ_НЕЙТРАЛІ["сім_ї"] else КОЛІР] += ваги[і] / разом
    for і, роль in enumerate(_РОЛІ_НЕЙТРАЛІ["ролі"]):
        сили[ВИД_РОЛІ[роль]] += ваги_ролей[і + 1] / разом
        сили[КОЛІР] -= ваги_ролей[і + 1] / разом
    сили[НЕВІДОМО] = ваги[-1] / разом
    return сили


def нейтраль_за_силами(сили):
    """Вид нейтралі за `сили_нейтралі`: вид із найбільшою силою, коли нейтраль сильніша за колір; `КОЛІР` — колір
    сильніший (на самій межі, при рівних силах, — колір: нейтраль має переважити); `НЕВІДОМО` — сила вузлів без
    даних більша за кожну з двох."""
    нейтраль = сили.get("ахроматична", 0.0) + сили.get("тепла", 0.0) + сили.get("холодна", 0.0)
    колір, невідомо = сили.get(КОЛІР, 0.0), сили.get(НЕВІДОМО, 0.0)
    if невідомо > нейтраль and невідомо > колір:
        return НЕВІДОМО
    if нейтраль <= колір:
        return КОЛІР
    return max(("ахроматична", "тепла", "холодна"), key=lambda к: сили.get(к, 0.0))


def нейтраль_кольору(lab, похибка=0.0):
    """Вид нейтралі K-COL-06 точки Lab («ахроматична», «тепла», «холодна»), `КОЛІР` чи `НЕВІДОМО`
    (`нейтраль_за_силами` над `сили_нейтралі`)."""
    return нейтраль_за_силами(сили_нейтралі(lab, похибка))


def стеля_нейтралей():
    """Найбільша C* вузла решітки, більша частина якого — нейтраль K-COL-06 (породжує генератор): обвідна, яка лише
    окреслює вікно нейтральної ролі; членство судить `нейтраль_кольору`."""
    return float(_РОЛІ_НЕЙТРАЛІ["стеля"])


